head.script:
scwin.onpageload = function() {
	scwin.data1 = [
		"0", "A", 1,
		"0", "A", 2,
		"0", "A", 3,
		"0", "B", 1,
		"0", "B", 2,
		"0", "B", 3,
		"0", "B", 4,
		"0", "C", 1,
		"0", "C", 2,
		"0", "C", 3,
		"0", "C", 4
	];
	dataList1.setData(scwin.data1.slice(0));
};
scwin.grid1_ongroupby = function(options) {
	options.closeGroup = true;
	options.rowNumHeader = {
		inputType: 'expression',
		expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
		align: 'left',
		colSpan: 5
	};
	options.rowNumFooter = {
		colSpan: 3
	};
	options.rowStatusFooter = {
		value: '합계'
	};
	options.groupbyFooter = [{
		inputType: 'expression',
		expression: 'SUM("col3")'
	}];
	this.groupby(options);
};
scwin.formatter = function(data) {
};
scwin.checkVal1 = function() {
	return ((j) => j.length ? j : $('.mf_w2grid_groupbyZone_list_listColumn_checkbox'))($('.w2grid_groupbyZone_list_listColumn_checkbox'))[1].checked == false;
};
