	return ((j) => j.length ? j : $('.mf_w2grid_groupbyZone_list_listColumn_checkbox'))($('.w2grid_groupbyZone_list_listColumn_checkbox'))[4].checked == false;
};
scwin.checkVal5 = function() {
	return ((j) => j.length ? j : $('.mf_w2grid_groupbyZone_list_listColumn_checkbox'))($('.w2grid_groupbyZone_list_listColumn_checkbox'))[1].checked == true;
};
